import { defineSchema, defineTable } from 'convex/server';
import { v } from 'convex/values';
export default defineSchema({
  users: defineTable({ phoneNumber:v.optional(v.string()), greetingSeenAt:v.optional(v.number()), safetyKind:v.optional(v.union(v.literal("medical"),v.literal("mental"))), safetyReturnAsked:v.optional(v.boolean()), clarificationChoices:v.optional(v.array(v.object({kind:v.union(v.literal('plan'),v.literal('symptom')),id:v.string()}))), memoryVersion: v.optional(v.number()), state: v.optional(v.union(v.literal('active'), v.literal('paused'), v.literal('stopped'))), dataDeletedAt: v.optional(v.number()), token: v.string(), label: v.string(), jobId: v.string(), timezone: v.string(), startDate: v.string(), endDate: v.string(), testNow: v.optional(v.number()), trackedItems: v.array(v.string()) }).index('by_token', ['token']).index('by_phone',['phoneNumber']),
  occurrences: defineTable({ userId: v.id('users'), jobId: v.string(), trackedItem: v.string(), rawText: v.string(), occurrenceDate: v.string(), occurrenceTime: v.union(v.string(), v.null()), timePrecision: v.union(v.literal('exact'), v.literal('approximate'), v.literal('date-only')), messageReceivedAt: v.number(), source: v.literal('user'), status: v.union(v.literal('active'), v.literal('corrected')), confirmationState: v.literal('confirmed'), batchId: v.string(), correctionText: v.optional(v.string()) }).index('by_user', ['userId']),
  pending: defineTable({ jobId: v.optional(v.string()), userId: v.id('users'), rawText: v.string(), messageReceivedAt: v.number(), reason: v.string(), kind: v.union(v.literal('clarification'), v.literal('possible_duplicate')), proposal: v.any(), relatedIds: v.array(v.id('occurrences')) }).index('by_user', ['userId']),
  receipts: defineTable({ replyEntry:v.optional(v.string()), repliedAt:v.optional(v.number()), answerHash:v.optional(v.string()), completionId:v.optional(v.id('planCompletions')), jobId:v.optional(v.string()), userState: v.optional(v.union(v.literal('active'), v.literal('paused'), v.literal('stopped'))), memoryVersion: v.optional(v.number()), userId: v.id('users'), messageId: v.string(), messageReceivedAt: v.optional(v.number()), state: v.string() }).index('by_user_message', ['userId', 'messageId']).index('by_user_state', ['userId', 'state']).index('by_user_reply_at',['userId','repliedAt']).index('by_user_reply_entry',['userId','replyEntry']),
  quotas: defineTable({ key: v.string(), times: v.array(v.number()) }).index('by_key', ['key']),
  references: defineTable({ userId: v.id('users'), jobId: v.string(), occurrenceId: v.id('occurrences') }).index('by_user', ['userId']).index('by_occurrence', ['occurrenceId']),
  proactiveOutputs: defineTable({userId: v.id('users'), jobId: v.string(), kind: v.union(v.literal('flag'), v.literal('correction'), v.literal('summary')), status: v.union(v.literal('queued'), v.literal('dropped')), body: v.optional(v.string())}).index('by_user', ['userId']).index('by_user_status', ['userId', 'status']),
  plans: defineTable({userId:v.id('users'),jobId:v.string(),activity:v.string(),targetNumber:v.number(),rawText:v.string(),messageReceivedAt:v.number(),confirmedAt:v.number(),state:v.union(v.literal('active'),v.literal('closed'))}).index('by_user',['userId']).index('by_user_job',['userId','jobId']),
  planCompletions: defineTable({userId:v.id('users'),jobId:v.string(),planId:v.id('plans'),rawText:v.string(),messageReceivedAt:v.number(),completionDate:v.string(),status:v.union(v.literal('completed'),v.literal('skipped')),correctionText:v.optional(v.string()),correctedAt:v.optional(v.number())}).index('by_user',['userId']).index('by_user_job',['userId','jobId']),
  planPending: defineTable({userId:v.id('users'),jobId:v.string(),rawText:v.string(),messageReceivedAt:v.number(),memoryVersion:v.number(),reason:v.string(),kind:v.union(v.literal('confirmation'),v.literal('date'),v.literal('duplicate'),v.literal('clarification')),proposal:v.any(),completionTargetId:v.optional(v.id('planCompletions'))}).index('by_user',['userId']).index('by_user_job',['userId','jobId']),
  deletionMarkers: defineTable({ jobId: v.string(), deletedAt: v.number() }),
});
